package redemption

// V-04 admission-trace replay (KC-VER H-01..H-07) against the real K-05
// attestation slot lock. Every trace generated by model/src/admission.rs is
// replayed step by step:
//
//   - Attest and Renew call the real Attester.lock on the real encrypted store
//     (store.Scoped through the fenced commit path).
//   - Crash closes and reopens that store; the durable history must survive.
//   - Tick, FinalizeTick, Admit, StateSpend, PolicyChange and ReadinessChange
//     are contract or chain actions. They drive a controlled C-04 reader
//     (H-03) whose custody history follows the model state block by block.
//   - ConfirmAbsence is the authenticated finalized-absence supplier fact. The
//     controlled reader answers the finalized custody read for a slot only
//     after the model confirmed absence for that slot; otherwise it reports
//     the finality read as unavailable.
//
// After every step the durable slot history (current plan and every plan ever
// attested, per slot) is compared with the model's locks and history. A
// weakened trace replays its claim-model steps cut at the first divergence
// (H-06). Contract-side guards (generation, version, expiry, identity,
// concurrency) are inputs here; C-04 tests own them, so those traces are
// "partial": host steps only. Planner.Validate, the certificate window check
// in Attest, key reload and seat signing are not exercised.
//
// Traces: V04_ADMISSION_TRACES, else the committed K-05 set (repaired
// model, 15 October). Report:
// V04_ADMISSION_REPORT (JSON) when set.

import (
	"context"
	"crypto/sha256"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"strings"
	"testing"

	"github.com/keep-network/keep-core/pkg/frost"
	"github.com/keep-network/keep-core/pkg/frost/store"
)

type admissionState struct {
	Tick               uint8    `json:"tick"`
	FinalizedTick      *uint8   `json:"finalized_tick"`
	AbsenceSlot        *uint8   `json:"absence_slot"`
	RenewedSlot        *uint8   `json:"renewed_slot"`
	ReplacementSlot    *uint8   `json:"replacement_slot"`
	Counter            uint8    `json:"counter"`
	Version            uint8    `json:"version"`
	Locks              [4]uint8 `json:"locks"`
	AttestationHistory [4]uint8 `json:"attestation_history"`
}

type admissionStep struct {
	N           int             `json:"n"`
	Action      json.RawMessage `json:"action"`
	ExpectState admissionState  `json:"expect_state"`
	Diverges    bool            `json:"diverges"`
}

type admissionTrace struct {
	ID              string          `json:"id"`
	Kind            string          `json:"kind"`
	Property        string          `json:"property"`
	Weakening       string          `json:"weakening"`
	Initial         admissionState  `json:"initial_state"`
	Steps           []admissionStep `json:"steps"`
	ClaimModelSteps []admissionStep `json:"claim_model_steps"`
}

// action decodes "Tick" or {"Attest":[g,v,p]} into a name and arguments.
func (s admissionStep) action() (string, []json.RawMessage, error) {
	var name string
	if json.Unmarshal(s.Action, &name) == nil {
		return name, nil, nil
	}
	var tagged map[string][]json.RawMessage
	if err := json.Unmarshal(s.Action, &tagged); err != nil || len(tagged) != 1 {
		return "", nil, fmt.Errorf("unknown action %s", s.Action)
	}
	for k, v := range tagged {
		return k, v, nil
	}
	return "", nil, nil
}

func uintArgs(raw []json.RawMessage, n int) ([]uint64, error) {
	if len(raw) < n {
		return nil, errors.New("short action")
	}
	out := make([]uint64, n)
	for i := 0; i < n; i++ {
		if err := json.Unmarshal(raw[i], &out[i]); err != nil {
			return nil, err
		}
	}
	return out, nil
}

var errFinalityUnauthenticated = errors.New("controlled reader: finalized absence not authenticated")

// admissionReader is the controlled C-04 reader. Only Custody is reachable from
// Attester.lock; every other Reader method panics through the nil interface.
type admissionReader struct {
	Reader
	wallet  [32]byte
	history []admissionCustody
	// authenticated is the slot whose finalized absence the supplier has
	// authenticated (the model's absence_slot); -1 for none.
	authenticated, querying int
	reads                   int
}

type admissionCustody struct {
	block   uint64
	custody Custody
}

func (r *admissionReader) Custody(_ context.Context, at uint64, wallet [32]byte) (Custody, error) {
	r.reads++
	if wallet != r.wallet {
		return Custody{}, ErrNotFound
	}
	if r.querying != r.authenticated {
		return Custody{}, errFinalityUnauthenticated
	}
	out := r.history[0].custody
	for _, h := range r.history {
		if h.block <= at {
			out = h.custody
		}
	}
	return out, nil
}

func (r *admissionReader) follow(s admissionState) {
	c := Custody{Generation: uint64(s.Counter), StateVersion: uint64(s.Version)}
	last := r.history[len(r.history)-1]
	if last.custody == c {
		return
	}
	if last.block == uint64(s.Tick) {
		r.history[len(r.history)-1].custody = c
		return
	}
	r.history = append(r.history, admissionCustody{uint64(s.Tick), c})
}

type admissionFence struct{ point store.Point }

func (f *admissionFence) Acquire(context.Context, [32]byte) (store.FenceLease, error) {
	return f, nil
}
func (f *admissionFence) Head(context.Context) (store.Point, error) { return f.point, nil }
func (f *admissionFence) Advance(_ context.Context, b, a store.Point) error {
	if b != f.point {
		return store.ErrQuarantined
	}
	f.point = a
	return nil
}
func (f *admissionFence) Close() error { return nil }

type admissionHarness struct {
	t        *testing.T
	ctx      context.Context
	config   store.Config
	domain   frost.Domain
	store    *store.Store
	reader   *admissionReader
	attester *Attester
	wallet   [32]byte
	reopens  int
}

func newAdmissionHarness(t *testing.T) *admissionHarness {
	wallet := sha256.Sum256([]byte("v04-admission-replay/wallet"))
	h := &admissionHarness{
		t:      t,
		ctx:    context.Background(),
		config: store.Config{Keystore: filepath.Join(t.TempDir(), "keystore"), StorageID: [32]byte{0xad}, Key: [32]byte{0x4a}, Fence: &admissionFence{}},
		domain: frost.Domain{Network: "V04/admission-replay", Chain: [32]byte{1}, Registry: [20]byte{2}, Wallet: wallet, Epoch: 1},
		reader: &admissionReader{wallet: wallet, history: []admissionCustody{{0, Custody{StateVersion: 1}}}, authenticated: -1},
		wallet: wallet,
	}
	h.open()
	t.Cleanup(func() { h.store.Close() })
	return h
}

func (h *admissionHarness) open() {
	s, err := store.Open(h.ctx, h.config)
	if err != nil {
		h.t.Fatal(err)
	}
	scoped, err := s.Scope(h.domain)
	if err != nil {
		h.t.Fatal(err)
	}
	h.store = s
	h.attester = &Attester{Planner: Planner{Chain: h.reader}, Journal: scoped}
}

// crash drops every volatile reference and reopens the durable store. The
// store has no volatile slot-lock state; this is a process restart.
func (h *admissionHarness) crash() {
	if err := h.store.Close(); err != nil {
		h.t.Fatal(err)
	}
	h.open()
	h.reopens++
}

func admissionSlot(g, v uint64) int { return int((g-1)*2 + (v - 1)) }

// statement is the certificate a host is asked to attest for (g, v, plan).
// Original, renewal and replacement certificates bind deadlines 1, 2 and 3.
func (h *admissionHarness) statement(g, v, plan, deadline uint64) Statement {
	p := sha256.Sum256([]byte(fmt.Sprintf("v04-admission-replay/plan/%d/%d/%d", g, v, plan)))
	return Statement{Plan: p, Certificate: Certificate{WalletID: h.wallet, DescriptorHash: [32]byte{0xde}, Generation: g, StateVersion: v, IntentCommitment: p, RequestIDsHash: [32]byte{0x1d}, ValidUntilBlock: deadline}}
}

func (h *admissionHarness) planOf(s Statement) uint8 {
	c := s.Certificate
	for plan := uint64(0); plan < 2; plan++ {
		if h.statement(c.Generation, c.StateVersion, plan, c.ValidUntilBlock).Plan == s.Plan {
			return uint8(plan)
		}
	}
	h.t.Fatalf("unknown plan in durable history")
	return 0
}

// observed reads the durable slot state: current plan bit and every plan bit.
func (h *admissionHarness) observed() (locks, history [4]uint8) {
	for g := uint64(1); g <= 2; g++ {
		for v := uint64(1); v <= 2; v++ {
			got, err := h.attester.History(h.ctx, h.wallet, g, v)
			if err != nil {
				h.t.Fatal(err)
			}
			slot := admissionSlot(g, v)
			for _, s := range got {
				history[slot] |= 1 << h.planOf(s)
			}
			if len(got) > 0 {
				locks[slot] = 1 << h.planOf(got[len(got)-1])
			}
		}
	}
	return
}

func finalizedNumber(s admissionState) uint64 {
	if s.FinalizedTick == nil {
		return 0
	}
	return uint64(*s.FinalizedTick)
}

func optionalSlot(v *uint8) int {
	if v == nil {
		return -1
	}
	return int(*v)
}

type admissionOutcome struct {
	hostSteps, chainSteps, compared int
	accepted, refused               int
}

// replayAdmission drives one step list. It returns the first mismatch.
func (h *admissionHarness) replay(steps []admissionStep, initial admissionState, r *admissionOutcome) error {
	pre := initial
	for _, step := range steps {
		name, raw, err := step.action()
		if err != nil {
			return err
		}
		post := step.ExpectState
		switch name {
		case "Attest", "Renew":
			args, err := uintArgs(raw, map[string]int{"Attest": 3, "Renew": 2}[name])
			if err != nil {
				return err
			}
			g, v := args[0], args[1]
			slot := admissionSlot(g, v)
			plan, deadline := uint64(0), uint64(1)
			if name == "Attest" {
				plan = args[2]
			}
			switch {
			case plan == 1:
				deadline = 3
			case name == "Renew" || optionalSlot(pre.RenewedSlot) == slot:
				deadline = 2
			}
			h.reader.authenticated, h.reader.querying = optionalSlot(pre.AbsenceSlot), slot
			err = h.attester.lock(h.ctx, Head{Number: finalizedNumber(pre)}, h.statement(g, v, plan, deadline))
			h.reader.querying = -2
			want := post.Locks[slot] == 1<<plan
			if err != nil && !errors.Is(err, ErrConflictingAttestation) && !errors.Is(err, errFinalityUnauthenticated) {
				return fmt.Errorf("step %d %s: unclassified error %v", step.N, step.Action, err)
			}
			if want != (err == nil) {
				return fmt.Errorf("step %d %s: model accepts=%v, lock err=%v", step.N, step.Action, want, err)
			}
			if err == nil {
				r.accepted++
			} else {
				r.refused++
			}
			r.hostSteps++
		case "Crash":
			h.crash()
			r.hostSteps++
		case "Tick", "FinalizeTick", "Admit", "StateSpend", "PolicyChange", "ReadinessChange", "ConfirmAbsence":
			h.reader.follow(post)
			r.chainSteps++
		default:
			return fmt.Errorf("step %d: unmapped action %s", step.N, name)
		}
		locks, history := h.observed()
		if locks != post.Locks || history != post.AttestationHistory {
			return fmt.Errorf("step %d %s: durable slots locks=%v history=%v, model locks=%v history=%v", step.N, step.Action, locks, history, post.Locks, post.AttestationHistory)
		}
		r.compared++
		pre = post
	}
	return nil
}

func admissionTraceDir(t *testing.T) string {
	if dir := os.Getenv("V04_ADMISSION_TRACES"); dir != "" {
		return dir
	}
	_, file, _, _ := runtime.Caller(0)
	return filepath.Join(filepath.Dir(file), "../signing/verification/evidence/V-04-K05-2026-10-15/admission-traces")
}

// hostLockWeakenings remove a host guard; their weakened expectations must
// fail on the real lock (negative control).
var hostLockWeakenings = map[string]bool{
	"ForgetTupleLocksOnCrash": true, "OmitTupleLock": true, "ReplaceBeforeInclusiveDeadline": true,
	"ReplaceWithoutFinalizedAbsence": true, "IgnoreOutstandingRenewal": true,
}

func TestV04AdmissionTraceReplay(t *testing.T) {
	dir := admissionTraceDir(t)
	paths, err := filepath.Glob(filepath.Join(dir, "*.json"))
	if err != nil || len(paths) == 0 {
		t.Fatalf("no admission traces in %s: %v", dir, err)
	}
	sort.Strings(paths)
	type row struct {
		ID, Kind, Weakening, Class, Note string
		Steps, Compared, Host, Chain     int
		Accepted, Refused                int
		Control                          string `json:",omitempty"`
	}
	var report []row
	for _, path := range paths {
		raw, err := os.ReadFile(path)
		if err != nil {
			t.Fatal(err)
		}
		var trace admissionTrace
		if err = json.Unmarshal(raw, &trace); err != nil {
			t.Fatal(path, err)
		}
		t.Run(trace.ID, func(t *testing.T) {
			steps := trace.Steps
			if trace.Weakening != "None" {
				steps = trace.ClaimModelSteps
			}
			var r admissionOutcome
			if err := newAdmissionHarness(t).replay(steps, trace.Initial, &r); err != nil {
				t.Fatalf("replay mismatch: %v", err)
			}
			class, note := "full", "every host step on the real lock and store; chain steps through the controlled reader"
			if trace.Weakening != "None" {
				class = "partial"
				note = "claim-model steps cut at the first divergence (H-06)"
				if !hostLockWeakenings[trace.Weakening] {
					note += "; contract-side guard is a controlled input, owned by C-04 tests"
				}
			}
			out := row{ID: trace.ID, Kind: trace.Kind, Weakening: trace.Weakening, Class: class, Note: note, Steps: len(steps), Compared: r.compared, Host: r.hostSteps, Chain: r.chainSteps, Accepted: r.accepted, Refused: r.refused}
			if hostLockWeakenings[trace.Weakening] {
				var w admissionOutcome
				err := newAdmissionHarness(t).replay(trace.Steps, trace.Initial, &w)
				if err == nil {
					t.Fatalf("negative control: weakened expectations of %s replayed on the real lock", trace.Weakening)
				}
				out.Control = "weakened expectations refused: " + err.Error()
			}
			t.Logf("V04_ADMISSION_REPLAY id=%s class=%s steps=%d compared=%d host=%d chain=%d accepted=%d refused=%d control=%q", out.ID, out.Class, out.Steps, out.Compared, out.Host, out.Chain, out.Accepted, out.Refused, out.Control)
			report = append(report, out)
		})
	}
	if path := os.Getenv("V04_ADMISSION_REPORT"); path != "" && !t.Failed() {
		raw, _ := json.MarshalIndent(report, "", "  ")
		if err := os.WriteFile(path, append(raw, '\n'), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	if !strings.HasSuffix(dir, "admission-traces") {
		t.Logf("trace directory %s", dir)
	}
}
